package dev.toka.profiles;
import org.junit.*;import static org.junit.Assert.*;
import com.google.gson.*;import java.nio.file.*;import java.util.*;
import dev.toka.profiles.migration.ProfileMigration;import dev.toka.storage.*;
public class MigrationTest {
 private Path root()throws Exception{Path base=Path.of(".build-tools/tests");Files.createDirectories(base);return Files.createTempDirectory(base,"migration-").toAbsolutePath();}
 private JsonArray rows(){JsonObject row=new JsonObject();row.addProperty("id",9);row.addProperty("name","Sunny");row.addProperty("UUID",UUID.randomUUID().toString());row.addProperty("FirstWindow",20261014);row.addProperty("qx",0);row.addProperty("jb",123);row.addProperty("lastLogoutIp","private-fixture");var a=new JsonArray();a.add(row);return a;}
 @Test public void threeImportsKeepSourceAndPrivateFieldsOutOfApi()throws Exception{for(Backend b:Backend.values()){Path root=root(),source=root.resolve("legacy.json");var rows=rows();String raw=rows.toString();Files.writeString(source,raw);var result=ProfileMigration.importFile(source,b,root.resolve("target"),root.resolve("backups"));assertEquals(1,result.profiles());assertEquals(raw,Files.readString(source));assertEquals(raw,Files.readString(result.backup()));try(var store=DocumentStore.open(new StoreConfig(b,result.destination(),1))){var profile=store.snapshot().values().iterator().next();assertEquals("20261014",profile.getAsJsonObject("preferences").get("firstWindowDate").getAsString());assertFalse(profile.has("jb"));assertFalse(profile.has("qx"));assertFalse(profile.has("lastLogoutIp"));}assertThrows(FileAlreadyExistsException.class,()->ProfileMigration.importFile(source,b,result.destination(),root.resolve("backups")));}}
 @Test public void unknownAndDuplicateIdentityStopsBeforeCreatingDestination()throws Exception{var rows=rows();rows.add(rows.get(0).deepCopy());assertThrows(IllegalArgumentException.class,()->ProfileMigration.prepare(rows));var missing=rows();missing.get(0).getAsJsonObject().addProperty("UUID","");assertThrows(IllegalArgumentException.class,()->ProfileMigration.prepare(missing));}
 @Test public void permissionPlanIsExplicitAndDoesNotGrantWebAdmin(){var source=rows();String plan=ProfileMigration.permissionPlan(source);assertTrue(plan.contains("toka.identity.admin true"));assertFalse(plan.contains("plan.webgroup.admin"));assertFalse(plan.contains(" permission set *"));source.get(0).getAsJsonObject().addProperty("qx",-1);assertThrows(IllegalArgumentException.class,()->ProfileMigration.permissionPlan(source));}
}
